void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096;

    // Update saved phases based on local best and random perturbation
    int phase_rand = rand() % 100;
    if (phase_rand < 60) {
        // Use local best phases
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (phase_rand < 80) {
        // Invert local best phases
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_rand < 95) {
        // Random phases
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        // Keep current saved phases (no change)
    }
}
